changeSet.sql:
DO $do$ DECLARE actor CONSTANT TEXT := 'di-resource-root-bootstrap'; resource_root_count INTEGER; unsafe_candidate_count INTEGER; BEGIN SELECT COUNT(*) INTO resource_root_count FROM portal_menu WHERE parent_id IS NULL AND deleted = FALSE AND metadata IS NOT NULL AND metadata::jsonb ->> 'key' = 'resource';
IF resource_root_count = 1 THEN RETURN; END IF; IF resource_root_count > 1 THEN RAISE EXCEPTION 'data-integration menu root metadata key resource is ambiguous before bootstrap: % rows', resource_root_count; END IF; IF NOT EXISTS (SELECT 1 FROM portal_menu) THEN RETURN; END IF;
SELECT COUNT(*) INTO unsafe_candidate_count FROM portal_menu WHERE name IN ( 'sys.nav.portal.resourceCenter', 'sys.nav.portal.dataIntegration', 'sys.nav.portal.resourceSources', 'sys.nav.portal.resourceIngestion', 'sys.nav.portal.resourceMetadata', 'sys.nav.portal.resourceChanges', 'sys.nav.portal.resourceConnectors', 'sys.nav.portal.resourceJdbcDrivers' ) OR path = 'resource' OR path LIKE 'resource/%' OR ( metadata IS NOT NULL AND ( metadata::jsonb ->> 'key' = 'resource' OR metadata::jsonb ->> 'sectionKey' = 'resource' OR metadata::jsonb ->> 'titleKey' IN ( 'sys.nav.portal.resourceCenter', 'sys.nav.portal.dataIntegration', 'sys.nav.portal.resourceSources', 'sys.nav.portal.resourceIngestion', 'sys.nav.portal.resourceMetadata', 'sys.nav.portal.resourceChanges', 'sys.nav.portal.resourceConnectors', 'sys.nav.portal.resourceJdbcDrivers' ) ) );
IF unsafe_candidate_count > 0 THEN RAISE EXCEPTION 'data-integration menu root is missing but % resource-like rows require manual reconciliation', unsafe_candidate_count; END IF;
INSERT INTO portal_menu ( name, path, component, sort_order, metadata, parent_id, icon, security_level, deleted, created_by, created_date, last_modified_by, last_modified_date ) VALUES ( 'sys.nav.portal.dataIntegration', 'resource', NULL, 2, '{"key":"resource","sectionKey":"resource","titleKey":"sys.nav.portal.dataIntegration","title":"数据集成","icon":"solar:database-bold-duotone"}', NULL, 'solar:database-bold-duotone', 'GENERAL', FALSE, actor, now(), actor, now() ); END $do$;

rollback.sql:
DO $do$
DECLARE
    actor CONSTANT TEXT := 'di-resource-root-bootstrap';
    allowed_descendant_actors CONSTANT TEXT[] := ARRAY[
        'data-integration-access-menu-convergence',
        'di-access-menu-v2',
        'di-profile-menu-20260801-02'
    ];
    resource_id BIGINT;
    resource_root_count INTEGER;
    descendant_ids BIGINT[] := ARRAY[]::BIGINT[];
    unsafe_row_count INTEGER;
BEGIN
    SELECT COUNT(*), MIN(id)
      INTO resource_root_count, resource_id
      FROM portal_menu
     WHERE parent_id IS NULL
       AND created_by = actor
       AND metadata IS NOT NULL
       AND metadata::jsonb ->> 'key' = 'resource';

    IF resource_root_count = 0 THEN
        RETURN;
    END IF;
    IF resource_root_count > 1 THEN
        RAISE EXCEPTION 'migration-owned data-integration roots are ambiguous during bootstrap rollback: % rows',
            resource_root_count;
    END IF;

    WITH RECURSIVE descendants AS (
        SELECT id
          FROM portal_menu
         WHERE parent_id = resource_id
        UNION ALL
        SELECT child.id
          FROM portal_menu child
          JOIN descendants parent ON child.parent_id = parent.id
    )
    SELECT COALESCE(ARRAY_AGG(id), ARRAY[]::BIGINT[])
      INTO descendant_ids
      FROM descendants;

    SELECT COUNT(*)
      INTO unsafe_row_count
      FROM portal_menu
     WHERE id = ANY(descendant_ids)
       AND (
           deleted = FALSE
           OR created_by IS NULL
           OR created_by <> ALL(allowed_descendant_actors)
       );

    IF unsafe_row_count > 0 THEN
        RAISE EXCEPTION 'data-integration bootstrap rollback found % active or non-migration descendant rows',
            unsafe_row_count;
    END IF;

    SELECT COUNT(*)
      INTO unsafe_row_count
      FROM portal_menu_visibility
     WHERE menu_id = resource_id OR menu_id = ANY(descendant_ids);

    IF unsafe_row_count > 0 THEN
        RAISE EXCEPTION 'data-integration bootstrap rollback found % visibility rows under the migration-owned root',
            unsafe_row_count;
    END IF;

    DELETE FROM portal_menu WHERE id = ANY(descendant_ids);
    DELETE FROM portal_menu WHERE id = resource_id AND created_by = actor;
END
$do$;
